const raw = $json.body ?? $json;
const headers = Object.fromEntries(
  Object.entries($json.headers ?? {}).map(([key, value]) => [key.toLowerCase(), value]),
);
const requiredSecret = $env.FMOTION_LINKEDIN_WEBHOOK_SECRET || '';
if (!requiredSecret) {
  throw new Error('FMOTION_LINKEDIN_WEBHOOK_SECRET is not set on n8n.');
}
if (headers['x-fmotion-linkedin-secret'] !== requiredSecret) {
  throw new Error('Invalid F-Motion LinkedIn webhook secret.');
}

const skip = raw.skip === true || raw.skip === 'true';
const text = String(raw.text || '').trim();
const url = String(raw.url || 'https://f-motion.com').trim() || 'https://f-motion.com';
const source = String(raw.source || '').trim() || null;

if (!skip && !text) {
  throw new Error('text is required unless skip is true.');
}
if (!skip && text.length > 2000) {
  throw new Error('text exceeds 2000 characters.');
}

return [{
  json: {
    skip,
    text,
    url,
    source,
  },
}];
